// ---- _shared/zoned.ts ----
// Timezone helpers shared by the web app and the Supabase Edge Function.
// Pure TypeScript, no dependencies: runs in browsers, Node and Deno.
// Dates are "YYYY-MM-DD" strings (local calendar dates); times are "HH:MM".

const formatters = new Map<string, Intl.DateTimeFormat>();

function formatter(tz: string): Intl.DateTimeFormat {
  let f = formatters.get(tz);
  if (!f) {
    f = new Intl.DateTimeFormat("en-US", {
      timeZone: tz,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      weekday: "short",
    });
    formatters.set(tz, f);
  }
  return f;
}

interface ZonedParts {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
  /** 0 = Sunday ... 6 = Saturday */
  weekday: number;
}

const WEEKDAYS: Record<string, number> = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

function isValidTimeZone(tz: string): boolean {
  try {
    formatter(tz).format(new Date(0));
    return true;
  } catch {
    return false;
  }
}

function zonedParts(date: Date, tz: string): ZonedParts {
  const parts = formatter(tz).formatToParts(date);
  const get = (type: string) => parts.find((p) => p.type === type)?.value ?? "0";
  let hour = Number(get("hour"));
  if (hour === 24) hour = 0;
  return {
    year: Number(get("year")),
    month: Number(get("month")),
    day: Number(get("day")),
    hour,
    minute: Number(get("minute")),
    second: Number(get("second")),
    weekday: WEEKDAYS[get("weekday")] ?? 0,
  };
}

const pad = (n: number, w = 2) => String(n).padStart(w, "0");

/** Local calendar date ("YYYY-MM-DD") of an instant in a timezone. */
function localDate(date: Date, tz: string): string {
  const p = zonedParts(date, tz);
  return `${pad(p.year, 4)}-${pad(p.month)}-${pad(p.day)}`;
}

/** Local wall-clock time ("HH:MM") of an instant in a timezone. */
function localTime(date: Date, tz: string): string {
  const p = zonedParts(date, tz);
  return `${pad(p.hour)}:${pad(p.minute)}`;
}

/** UTC offset of a timezone at an instant, in minutes (Seoul = +540). */
function tzOffsetMinutes(date: Date, tz: string): number {
  const p = zonedParts(date, tz);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  const actual = Math.floor(date.getTime() / 1000) * 1000;
  return Math.round((asUtc - actual) / 60000);
}

function parseDate(dateStr: string): { year: number; month: number; day: number } {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) throw new Error(`Invalid date: ${dateStr}`);
  return { year: Number(m[1]), month: Number(m[2]), day: Number(m[3]) };
}

function parseTime(time: string): { hour: number; minute: number } {
  const m = /^(\d{2}):(\d{2})$/.exec(time);
  if (!m) throw new Error(`Invalid time: ${time}`);
  const hour = Number(m[1]);
  const minute = Number(m[2]);
  if (hour > 23 || minute > 59) throw new Error(`Invalid time: ${time}`);
  return { hour, minute };
}

/**
 * Converts a local wall-clock date + time in `tz` to the UTC instant.
 * Daylight-saving rules (same convention as Temporal's "compatible"):
 *  - time that does not exist (spring-forward gap) moves forward by the gap;
 *  - time that occurs twice (fall-back overlap) uses the first occurrence.
 */
function zonedTimeToUtc(dateStr: string, time: string, tz: string): Date {
  const { year, month, day } = parseDate(dateStr);
  const { hour, minute } = parseTime(time);
  const guess = Date.UTC(year, month - 1, day, hour, minute);
  const HOUR = 3600_000;
  const offsets = Array.from(
    new Set([-14, 0, 14].map((h) => tzOffsetMinutes(new Date(guess + h * HOUR), tz))),
  );
  const valid: number[] = [];
  for (const off of offsets) {
    const t = guess - off * 60000;
    const p = zonedParts(new Date(t), tz);
    if (p.year === year && p.month === month && p.day === day && p.hour === hour && p.minute === minute) {
      valid.push(t);
    }
  }
  if (valid.length > 0) return new Date(Math.min(...valid));
  // Gap: use the offset in force before the transition.
  const before = tzOffsetMinutes(new Date(guess - 14 * HOUR), tz);
  return new Date(guess - before * 60000);
}

function addDays(dateStr: string, days: number): string {
  const { year, month, day } = parseDate(dateStr);
  const d = new Date(Date.UTC(year, month - 1, day + days));
  return `${pad(d.getUTCFullYear(), 4)}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
}

/** Whole days from a to b (b - a). */
function daysBetween(a: string, b: string): number {
  const pa = parseDate(a);
  const pb = parseDate(b);
  return Math.round(
    (Date.UTC(pb.year, pb.month - 1, pb.day) - Date.UTC(pa.year, pa.month - 1, pa.day)) / 86400_000,
  );
}

/** 0 = Sunday ... 6 = Saturday */
function weekdayOf(dateStr: string): number {
  const { year, month, day } = parseDate(dateStr);
  return new Date(Date.UTC(year, month - 1, day)).getUTCDay();
}

/** Monday of the ISO week containing the date. */
function mondayOf(dateStr: string): string {
  const wd = weekdayOf(dateStr);
  return addDays(dateStr, wd === 0 ? -6 : 1 - wd);
}

function timeToMinutes(time: string): number {
  const { hour, minute } = parseTime(time);
  return hour * 60 + minute;
}

function minutesToTime(total: number): string {
  const m = ((total % 1440) + 1440) % 1440;
  return `${pad(Math.floor(m / 60))}:${pad(m % 60)}`;
}

// ---- _shared/reminders.ts ----
// Decides which reminders are due. Shared by the Edge Function (production
// scheduler) and the unit tests. No I/O here: callers pass rows in.

interface ReminderItem {
  id: string;
  title: string;
  time_local: string; // "HH:MM" wall-clock time in the user's timezone
  reminder_enabled: boolean;
  /** Weekdays the item applies to, 0 = Sunday. Empty/null = every day. */
  days?: number[] | null;
  notify_body?: string | null;
  deleted?: boolean | null;
  updated_at?: string | null;
}

interface Completion {
  local_date: string;
  item_id: string;
  status: "completed" | "skipped";
  deleted?: boolean | null;
}

interface DueReminder {
  itemId: string;
  title: string;
  body: string;
  localDate: string;
  time: string;
  fireAt: Date;
  dedupeKey: string;
}

/**
 * Stable identifier of one reminder occurrence. Includes the scheduled time,
 * so editing a time creates a new occurrence and the old one can never match
 * again; the database enforces uniqueness of this key, so the same occurrence
 * can only be claimed (and sent) once even if the scheduler runs twice.
 */
function reminderKey(userId: string, itemId: string, date: string, time: string): string {
  return `r:${userId}:${itemId}:${date}:${time}`;
}

function snoozeKey(userId: string, snoozeId: string): string {
  return `s:${userId}:${snoozeId}`;
}

function itemActiveOn(item: Pick<ReminderItem, "days">, date: string): boolean {
  if (!item.days || item.days.length === 0) return true;
  return item.days.includes(weekdayOf(date));
}

interface DueOptions {
  userId: string;
  now: Date;
  timeZone: string;
  items: ReminderItem[];
  completions: Completion[];
  /** How late a reminder may still be sent if a scheduler tick was missed. */
  catchUpMinutes?: number;
}

function dueReminders(opts: DueOptions): DueReminder[] {
  const { userId, now, timeZone, items, completions } = opts;
  const windowMs = (opts.catchUpMinutes ?? 10) * 60000;
  const today = localDate(now, timeZone);
  const done = new Set(
    completions.filter((c) => !c.deleted).map((c) => `${c.local_date}|${c.item_id}`),
  );
  const out: DueReminder[] = [];
  // Yesterday is included so reminders just before midnight are not lost.
  for (const date of [addDays(today, -1), today]) {
    for (const item of items) {
      if (item.deleted || !item.reminder_enabled) continue;
      if (!itemActiveOn(item, date)) continue;
      if (done.has(`${date}|${item.id}`)) continue;
      let fireAt: Date;
      try {
        fireAt = zonedTimeToUtc(date, item.time_local, timeZone);
      } catch {
        continue; // malformed time: never crash the scheduler
      }
      const age = now.getTime() - fireAt.getTime();
      if (age < 0 || age >= windowMs) continue;
      // An edit made after this occurrence's time sets up future days only;
      // it must not fire a "late" reminder for a time that already passed.
      if (item.updated_at && Date.parse(item.updated_at) > fireAt.getTime()) continue;
      out.push({
        itemId: item.id,
        title: item.title,
        body: item.notify_body || `${item.title} — scheduled for ${formatTime12(item.time_local)}`,
        localDate: date,
        time: item.time_local,
        fireAt,
        dedupeKey: reminderKey(userId, item.id, date, item.time_local),
      });
    }
  }
  return out;
}

function formatTime12(time: string): string {
  const [h, m] = time.split(":").map(Number);
  const suffix = h >= 12 ? "PM" : "AM";
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(m).padStart(2, "0")} ${suffix}`;
}

// ---- _shared/webpush.ts ----
// Standards-based Web Push sender using only the Web Crypto API, so the same
// code runs in Deno (Supabase Edge Functions), Node 20+ and browsers.
//  - Message encryption: RFC 8291 (aes128gcm content coding, RFC 8188)
//  - Sender authentication: RFC 8292 (VAPID, ES256 JWT)

interface PushSubscriptionKeys {
  endpoint: string;
  p256dh: string; // base64url, 65-byte uncompressed P-256 point
  auth: string; // base64url, 16 bytes
}

interface VapidKeys {
  publicKey: string; // base64url, 65-byte uncompressed P-256 point
  privateKey: string; // base64url, 32-byte scalar "d"
  subject: string; // "mailto:you@example.com" or an https URL
}

interface SendOptions {
  ttlSeconds?: number;
  urgency?: "very-low" | "low" | "normal" | "high";
  /** Push services replace a not-yet-delivered message with the same topic. */
  topic?: string;
}

interface SendResult {
  ok: boolean;
  status: number;
  /** true when the subscription is permanently invalid (404/410). */
  gone: boolean;
  body?: string;
}

const enc = new TextEncoder();

function b64urlEncode(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function b64urlDecode(str: string): Uint8Array {
  const s = str.replace(/-/g, "+").replace(/_/g, "/");
  const padded = s + "===".slice((s.length + 3) % 4);
  const bin = atob(padded);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function concat(...parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((n, p) => n + p.length, 0);
  const out = new Uint8Array(total);
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return out;
}

// Typed-array → ArrayBuffer copy (avoids SharedArrayBuffer typing issues).
function buf(u: Uint8Array): ArrayBuffer {
  return u.slice().buffer as ArrayBuffer;
}

async function hkdf(salt: Uint8Array, ikm: Uint8Array, info: Uint8Array, length: number): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey("raw", buf(ikm), "HKDF", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits(
    { name: "HKDF", hash: "SHA-256", salt: buf(salt), info: buf(info) },
    key,
    length * 8,
  );
  return new Uint8Array(bits);
}

/** Encrypts a payload for one subscription (RFC 8291, single record). */
async function encryptPayload(
  payload: Uint8Array,
  p256dh: string,
  authSecret: string,
  testing?: { salt?: Uint8Array; keyPair?: CryptoKeyPair },
): Promise<Uint8Array> {
  const uaPublic = b64urlDecode(p256dh);
  const auth = b64urlDecode(authSecret);
  if (uaPublic.length !== 65 || uaPublic[0] !== 4) throw new Error("Invalid p256dh key");
  if (auth.length < 16) throw new Error("Invalid auth secret");

  const asKeys =
    testing?.keyPair ??
    ((await crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"])) as CryptoKeyPair);
  const asPublic = new Uint8Array(await crypto.subtle.exportKey("raw", asKeys.publicKey));
  const uaKey = await crypto.subtle.importKey("raw", buf(uaPublic), { name: "ECDH", namedCurve: "P-256" }, false, []);
  const ecdhSecret = new Uint8Array(
    await crypto.subtle.deriveBits({ name: "ECDH", public: uaKey }, asKeys.privateKey, 256),
  );

  const keyInfo = concat(enc.encode("WebPush: info\0"), uaPublic, asPublic);
  const ikm = await hkdf(auth, ecdhSecret, keyInfo, 32);
  const salt = testing?.salt ?? crypto.getRandomValues(new Uint8Array(16));
  const cek = await hkdf(salt, ikm, enc.encode("Content-Encoding: aes128gcm\0"), 16);
  const nonce = await hkdf(salt, ikm, enc.encode("Content-Encoding: nonce\0"), 12);

  const recordSize = 4096;
  const plaintext = concat(payload, new Uint8Array([2])); // 0x02 = last record delimiter
  if (plaintext.length + 16 > recordSize) throw new Error("Payload too large for one record");
  const aesKey = await crypto.subtle.importKey("raw", buf(cek), "AES-GCM", false, ["encrypt"]);
  const ciphertext = new Uint8Array(
    await crypto.subtle.encrypt({ name: "AES-GCM", iv: buf(nonce), tagLength: 128 }, aesKey, buf(plaintext)),
  );

  const header = new Uint8Array(16 + 4 + 1 + asPublic.length);
  header.set(salt, 0);
  new DataView(header.buffer).setUint32(16, recordSize);
  header[20] = asPublic.length;
  header.set(asPublic, 21);
  return concat(header, ciphertext);
}

async function importVapidPrivateKey(vapid: VapidKeys): Promise<CryptoKey> {
  const pub = b64urlDecode(vapid.publicKey);
  if (pub.length !== 65 || pub[0] !== 4) throw new Error("Invalid VAPID public key");
  const jwk: JsonWebKey = {
    kty: "EC",
    crv: "P-256",
    d: vapid.privateKey,
    x: b64urlEncode(pub.slice(1, 33)),
    y: b64urlEncode(pub.slice(33, 65)),
    ext: true,
  };
  return crypto.subtle.importKey("jwk", jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
}

/** Builds the VAPID Authorization header value for a push endpoint. */
async function vapidAuthorization(endpoint: string, vapid: VapidKeys, nowSeconds?: number): Promise<string> {
  const aud = new URL(endpoint).origin;
  const now = nowSeconds ?? Math.floor(Date.now() / 1000);
  const header = b64urlEncode(enc.encode(JSON.stringify({ typ: "JWT", alg: "ES256" })));
  const claims = b64urlEncode(enc.encode(JSON.stringify({ aud, exp: now + 12 * 3600, sub: vapid.subject })));
  const signingInput = `${header}.${claims}`;
  const key = await importVapidPrivateKey(vapid);
  const sig = new Uint8Array(
    await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, buf(enc.encode(signingInput))),
  );
  return `vapid t=${signingInput}.${b64urlEncode(sig)}, k=${vapid.publicKey}`;
}

/** Push service topic: max 32 chars from the URL-safe base64 alphabet. */
async function topicFor(key: string): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", buf(enc.encode(key))));
  return b64urlEncode(digest).slice(0, 32);
}

async function sendWebPush(
  sub: PushSubscriptionKeys,
  payload: unknown,
  vapid: VapidKeys,
  options: SendOptions = {},
  fetchImpl: typeof fetch = fetch,
): Promise<SendResult> {
  const body = await encryptPayload(enc.encode(JSON.stringify(payload)), sub.p256dh, sub.auth);
  const headers: Record<string, string> = {
    Authorization: await vapidAuthorization(sub.endpoint, vapid),
    "Content-Encoding": "aes128gcm",
    "Content-Type": "application/octet-stream",
    TTL: String(options.ttlSeconds ?? 3600),
    Urgency: options.urgency ?? "high",
  };
  if (options.topic) headers.Topic = options.topic;
  const res = await fetchImpl(sub.endpoint, { method: "POST", headers, body: buf(body) });
  const text = res.ok ? undefined : (await res.text().catch(() => "")).slice(0, 300);
  return { ok: res.status >= 200 && res.status < 300, status: res.status, gone: res.status === 404 || res.status === 410, body: text };
}

/** Generates a VAPID key pair (base64url public point + private scalar). */
async function generateVapidKeys(): Promise<{ publicKey: string; privateKey: string }> {
  const kp = (await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"])) as CryptoKeyPair;
  const pub = new Uint8Array(await crypto.subtle.exportKey("raw", kp.publicKey));
  const jwk = await crypto.subtle.exportKey("jwk", kp.privateKey);
  return { publicKey: b64urlEncode(pub), privateKey: jwk.d as string };
}

// ---- _shared/scheduler.ts ----
// The production reminder scheduler, written against a small storage
// interface so it can be unit-tested with an in-memory store and run in the
// Edge Function with Supabase.



interface StoredSubscription extends PushSubscriptionKeys {
  id: string;
  user_id: string;
}

interface UserContext {
  userId: string;
  timeZone: string;
}

interface Snooze {
  id: string;
  user_id: string;
  item_id: string;
  local_date: string;
  title: string;
  fire_at: string;
}

interface NewLog {
  id: string;
  user_id: string;
  dedupe_key: string;
  kind: "reminder" | "snooze" | "test";
  item_id: string | null;
  local_date: string | null;
  scheduled_for: string;
  receipt_token: string;
  title: string;
  body: string;
}

interface LogResult {
  status: "sent" | "failed" | "no_subscription";
  sent_at: string | null;
  success_count: number;
  failure_count: number;
  error: string | null;
}

interface SchedulerStore {
  /** Users that have push enabled and at least one active subscription. */
  activeUsers(): Promise<UserContext[]>;
  items(userId: string): Promise<ReminderItem[]>;
  completions(userId: string, dates: string[]): Promise<Completion[]>;
  subscriptions(userId: string): Promise<StoredSubscription[]>;
  dueSnoozes(now: Date): Promise<Snooze[]>;
  markSnoozeSent(id: string, at: Date): Promise<void>;
  /** Inserts the log row unless dedupe_key exists. true = this caller owns it. */
  claim(log: NewLog): Promise<boolean>;
  finish(logId: string, result: LogResult): Promise<void>;
  subscriptionResult(subId: string, result: SendResult, at: Date): Promise<void>;
}

type Sender = (sub: PushSubscriptionKeys, payload: unknown, options: SendOptions) => Promise<SendResult>;

interface TickDeps {
  store: SchedulerStore;
  send: Sender;
  now: Date;
  /** Public URL of the receipt endpoint, called by the service worker. */
  receiptUrl: string;
  newId: () => string;
  newToken: () => string;
  appPath?: string;
}

interface TickSummary {
  users: number;
  due: number;
  claimed: number;
  sent: number;
  failed: number;
}

interface PushPayload {
  title: string;
  body: string;
  tag: string;
  url: string;
  kind: NewLog["kind"];
  item_id: string | null;
  local_date: string | null;
  log_id: string;
  receipt_url: string;
  receipt_token: string;
}

async function deliver(
  deps: Pick<TickDeps, "store" | "send" | "now">,
  log: NewLog,
  payload: PushPayload,
  subs: StoredSubscription[],
): Promise<{ result: LogResult; perSubscription: Array<{ subscription_id: string; host: string } & SendResult> }> {
  const perSubscription: Array<{ subscription_id: string; host: string } & SendResult> = [];
  const topic = await topicFor(log.dedupe_key);
  for (const sub of subs) {
    let r: SendResult;
    try {
      r = await deps.send(sub, payload, {
        topic,
        urgency: "high",
        // A reminder that arrives hours late is useless; tests may wait longer.
        ttlSeconds: log.kind === "test" ? 600 : 1800,
      });
    } catch (e) {
      r = { ok: false, status: 0, gone: false, body: String(e).slice(0, 300) };
    }
    await deps.store.subscriptionResult(sub.id, r, deps.now);
    let host = "";
    try {
      host = new URL(sub.endpoint).host;
    } catch {
      host = "invalid";
    }
    perSubscription.push({ subscription_id: sub.id, host, ...r });
  }
  const ok = perSubscription.filter((p) => p.ok).length;
  const failed = perSubscription.length - ok;
  const result: LogResult = {
    status: subs.length === 0 ? "no_subscription" : ok > 0 ? "sent" : "failed",
    sent_at: ok > 0 ? deps.now.toISOString() : null,
    success_count: ok,
    failure_count: failed,
    error:
      failed > 0
        ? perSubscription
            .filter((p) => !p.ok)
            .map((p) => `${p.host}: HTTP ${p.status}${p.body ? ` ${p.body}` : ""}`)
            .join("; ")
            .slice(0, 500)
        : null,
  };
  await deps.store.finish(log.id, result);
  return { result, perSubscription };
}

function payloadFor(log: NewLog, deps: Pick<TickDeps, "receiptUrl" | "appPath">): PushPayload {
  const base = deps.appPath ?? "./";
  const url = log.item_id ? `${base}?focus=${encodeURIComponent(log.item_id)}` : base;
  return {
    title: log.title,
    body: log.body,
    tag: log.item_id ? `${log.item_id}:${log.local_date}` : log.dedupe_key,
    url,
    kind: log.kind,
    item_id: log.item_id,
    local_date: log.local_date,
    log_id: log.id,
    receipt_url: deps.receiptUrl,
    receipt_token: log.receipt_token,
  };
}

/** One scheduler tick (called every minute by pg_cron). */
async function runReminderTick(deps: TickDeps): Promise<TickSummary> {
  const { store, now } = deps;
  const summary: TickSummary = { users: 0, due: 0, claimed: 0, sent: 0, failed: 0 };
  const users = await store.activeUsers();
  summary.users = users.length;

  for (const user of users) {
    const today = localDate(now, user.timeZone);
    const [items, completions] = await Promise.all([
      store.items(user.userId),
      store.completions(user.userId, [addDays(today, -1), today]),
    ]);
    const due = dueReminders({ userId: user.userId, now, timeZone: user.timeZone, items, completions });
    summary.due += due.length;
    if (due.length === 0) continue;
    const subs = await store.subscriptions(user.userId);
    for (const r of due) {
      const log: NewLog = {
        id: deps.newId(),
        user_id: user.userId,
        dedupe_key: r.dedupeKey,
        kind: "reminder",
        item_id: r.itemId,
        local_date: r.localDate,
        scheduled_for: r.fireAt.toISOString(),
        receipt_token: deps.newToken(),
        title: r.title,
        body: r.body,
      };
      if (!(await store.claim(log))) continue; // already sent by an earlier tick
      summary.claimed++;
      const { result } = await deliver(deps, log, payloadFor(log, deps), subs);
      if (result.status === "sent") summary.sent++;
      else summary.failed++;
    }
  }

  // Snoozed reminders ("remind me again in 10 minutes").
  const snoozes = await store.dueSnoozes(now);
  for (const s of snoozes) {
    await store.markSnoozeSent(s.id, now);
    const completions = await store.completions(s.user_id, [s.local_date]);
    if (completions.some((c) => !c.deleted && c.item_id === s.item_id && c.local_date === s.local_date)) continue;
    summary.due++;
    const log: NewLog = {
      id: deps.newId(),
      user_id: s.user_id,
      dedupe_key: snoozeKey(s.user_id, s.id),
      kind: "snooze",
      item_id: s.item_id,
      local_date: s.local_date,
      scheduled_for: s.fire_at,
      receipt_token: deps.newToken(),
      title: s.title,
      body: `Snoozed reminder: ${s.title}`,
    };
    if (!(await store.claim(log))) continue;
    summary.claimed++;
    const subs = await store.subscriptions(s.user_id);
    const { result } = await deliver(deps, log, payloadFor(log, deps), subs);
    if (result.status === "sent") summary.sent++;
    else summary.failed++;
  }
  return summary;
}

/** Sends a test notification right away and reports what really happened. */
async function sendTestNotification(
  deps: Omit<TickDeps, "now"> & { now: Date; userId: string },
): Promise<{
  log_id: string;
  status: LogResult["status"];
  results: Array<{ subscription_id: string; host: string; ok: boolean; status: number; gone: boolean; body?: string }>;
}> {
  const log: NewLog = {
    id: deps.newId(),
    user_id: deps.userId,
    dedupe_key: `t:${deps.userId}:${deps.newId()}`,
    kind: "test",
    item_id: null,
    local_date: null,
    scheduled_for: deps.now.toISOString(),
    receipt_token: deps.newToken(),
    title: "FitFlow test notification",
    body: "If you can read this, reminders can reach this device.",
  };
  await deps.store.claim(log);
  const subs = await deps.store.subscriptions(deps.userId);
  const { result, perSubscription } = await deliver(deps, log, payloadFor(log, deps), subs);
  return { log_id: log.id, status: result.status, results: perSubscription };
}

// ---- fitflow/index.ts ----
// FitFlow Edge Function (Supabase, Deno runtime).
// Routes (POST):
//   /fitflow/cron     called every minute by pg_cron; header x-cron-secret
//   /fitflow/test     signed-in user: send a test notification now
//   /fitflow/receipt  service worker: confirms a notification was shown
//   /fitflow/delete-account  signed-in user: delete account + all data
// Deploy with JWT verification OFF (this file authorizes every route itself):
//   npx supabase functions deploy fitflow --no-verify-jwt




const env = (k: string) => Deno.env.get(k) ?? "";

function firstKey(jsonDict: string): string {
  try {
    const d = JSON.parse(jsonDict) as Record<string, string>;
    return d.default ?? Object.values(d)[0] ?? "";
  } catch {
    return "";
  }
}

const SUPABASE_URL = env("SUPABASE_URL");
const SECRET_KEY = firstKey(env("SUPABASE_SECRET_KEYS")) || env("SUPABASE_SERVICE_ROLE_KEY");
const PUBLISHABLE_KEY = firstKey(env("SUPABASE_PUBLISHABLE_KEYS")) || env("SUPABASE_ANON_KEY");
const CRON_SECRET = env("CRON_SECRET");
const ALLOWED_ORIGIN = env("ALLOWED_ORIGIN") || "*";
const vapid: VapidKeys = {
  publicKey: env("VAPID_PUBLIC_KEY"),
  privateKey: env("VAPID_PRIVATE_KEY"),
  subject: env("VAPID_SUBJECT") || "mailto:fitflow@example.com",
};

const admin: SupabaseClient = createClient(SUPABASE_URL, SECRET_KEY, {
  auth: { persistSession: false, autoRefreshToken: false },
});

const cors = {
  "Access-Control-Allow-Origin": ALLOWED_ORIGIN,
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info, x-cron-secret",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json" } });

function timingSafeEqual(a: string, b: string): boolean {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const randomToken = () => {
  const b = crypto.getRandomValues(new Uint8Array(24));
  return Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
};

function must<T>(res: { data: T | null; error: { message: string } | null }): T {
  if (res.error) throw new Error(res.error.message);
  return res.data as T;
}

const store: SchedulerStore = {
  async activeUsers() {
    const subs = must(
      await admin.from("push_subscriptions").select("user_id").is("disabled_at", null),
    ) as Array<{ user_id: string }>;
    const ids = [...new Set(subs.map((s) => s.user_id))];
    if (ids.length === 0) return [];
    const prefs = must(
      await admin.from("reminder_preferences").select("user_id, push_enabled").in("user_id", ids).eq("deleted", false),
    ) as Array<{ user_id: string; push_enabled: boolean }>;
    const disabled = new Set(prefs.filter((p) => p.push_enabled === false).map((p) => p.user_id));
    const profiles = must(
      await admin.from("profiles").select("user_id, timezone").in("user_id", ids),
    ) as Array<{ user_id: string; timezone: string }>;
    const tz = new Map(profiles.map((p) => [p.user_id, p.timezone]));
    return ids
      .filter((id) => !disabled.has(id))
      .map((id) => {
        const t = tz.get(id) ?? "Asia/Seoul";
        return { userId: id, timeZone: isValidTimeZone(t) ? t : "Asia/Seoul" };
      });
  },
  async items(userId) {
    return must(
      await admin
        .from("schedule_items")
        .select("id, title, time_local, reminder_enabled, days, notify_body, deleted, updated_at")
        .eq("user_id", userId)
        .eq("deleted", false),
    );
  },
  async completions(userId, dates) {
    return must(
      await admin
        .from("task_completions")
        .select("local_date, item_id, status, deleted")
        .eq("user_id", userId)
        .in("local_date", dates)
        .eq("deleted", false),
    );
  },
  async subscriptions(userId) {
    return must(
      await admin
        .from("push_subscriptions")
        .select("id, user_id, endpoint, p256dh, auth")
        .eq("user_id", userId)
        .is("disabled_at", null),
    );
  },
  async dueSnoozes(now) {
    const since = new Date(now.getTime() - 30 * 60000).toISOString();
    return must(
      await admin
        .from("snoozes")
        .select("id, user_id, item_id, local_date, title, fire_at")
        .is("sent_at", null)
        .lte("fire_at", now.toISOString())
        .gte("fire_at", since),
    );
  },
  async markSnoozeSent(id, at) {
    must(await admin.from("snoozes").update({ sent_at: at.toISOString() }).eq("id", id));
  },
  async claim(log) {
    const rows = must(
      await admin
        .from("notification_log")
        .upsert({ ...log, status: "sending" }, { onConflict: "dedupe_key", ignoreDuplicates: true })
        .select("id"),
    ) as Array<{ id: string }>;
    return rows.length > 0;
  },
  async finish(logId, result) {
    must(await admin.from("notification_log").update(result).eq("id", logId));
  },
  async subscriptionResult(subId, r, at) {
    if (r.ok) {
      must(
        await admin
          .from("push_subscriptions")
          .update({ last_success_at: at.toISOString(), failure_count: 0, last_error: null })
          .eq("id", subId),
      );
      return;
    }
    const current = must(
      await admin.from("push_subscriptions").select("failure_count").eq("id", subId).maybeSingle(),
    ) as { failure_count: number } | null;
    const failures = (current?.failure_count ?? 0) + 1;
    must(
      await admin
        .from("push_subscriptions")
        .update({
          last_failure_at: at.toISOString(),
          failure_count: failures,
          last_error: `HTTP ${r.status} ${r.body ?? ""}`.slice(0, 300),
          // Expired (404/410) or repeatedly failing subscriptions stop being used.
          ...(r.gone || failures >= 10 ? { disabled_at: at.toISOString(), disabled_reason: r.gone ? "expired" : "failing" } : {}),
        })
        .eq("id", subId),
    );
  },
};

const send = (sub: { endpoint: string; p256dh: string; auth: string }, payload: unknown, options: object) =>
  sendWebPush(sub, payload, vapid, options);

async function userFrom(req: Request): Promise<string | null> {
  const token = (req.headers.get("authorization") ?? "").replace(/^Bearer\s+/i, "");
  if (!token) return null;
  const { data, error } = await admin.auth.getUser(token);
  if (error || !data.user) return null;
  return data.user.id;
}

function receiptUrl(): string {
  const u = `${SUPABASE_URL}/functions/v1/fitflow/receipt`;
  return PUBLISHABLE_KEY ? `${u}?apikey=${encodeURIComponent(PUBLISHABLE_KEY)}` : u;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
  if (req.method !== "POST") return json({ error: "Use POST" }, 405);
  const route = new URL(req.url).pathname.split("/").filter(Boolean).pop();

  try {
    if (route === "cron") {
      if (!timingSafeEqual(req.headers.get("x-cron-secret") ?? "", CRON_SECRET)) {
        return json({ error: "Forbidden" }, 403);
      }
      if (!vapid.publicKey || !vapid.privateKey) return json({ error: "VAPID keys not configured" }, 500);
      const summary = await runReminderTick({
        store,
        send,
        now: new Date(),
        receiptUrl: receiptUrl(),
        newId: () => crypto.randomUUID(),
        newToken: randomToken,
      });
      // Housekeeping once an hour: keep 120 days of delivery history.
      if (new Date().getUTCMinutes() === 7) {
        const cutoff = new Date(Date.now() - 120 * 86400_000).toISOString();
        await admin.from("notification_log").delete().lt("created_at", cutoff);
        await admin.from("snoozes").delete().lt("fire_at", cutoff);
      }
      return json({ ok: true, ...summary });
    }

    if (route === "receipt") {
      const { token } = (await req.json().catch(() => ({}))) as { token?: string };
      if (!token || token.length < 32) return json({ error: "Bad token" }, 400);
      await admin
        .from("notification_log")
        .update({ delivered_at: new Date().toISOString() })
        .eq("receipt_token", token)
        .is("delivered_at", null);
      return json({ ok: true });
    }

    const userId = await userFrom(req);
    if (!userId) return json({ error: "Sign in required" }, 401);

    if (route === "test") {
      if (!vapid.publicKey || !vapid.privateKey) return json({ error: "VAPID keys not configured on the server" }, 500);
      const result = await sendTestNotification({
        store,
        send,
        now: new Date(),
        userId,
        receiptUrl: receiptUrl(),
        newId: () => crypto.randomUUID(),
        newToken: randomToken,
      });
      return json(result);
    }

    if (route === "delete-account") {
      const { error } = await admin.auth.admin.deleteUser(userId);
      if (error) return json({ error: error.message }, 500);
      return json({ ok: true }); // all tables cascade on auth.users deletion
    }

    return json({ error: "Unknown route" }, 404);
  } catch (e) {
    console.error(e);
    return json({ error: String((e as Error).message ?? e) }, 500);
  }
});
